#' @title Load and prepare data inputs
#' @export
#' @description Loads input files, aggregates basedata and
#'   parameters according to set mappings, and returns prepared
#'   data for [`ems_deploy()`]. Accepts GTAP HAR files and
#'   objects generated by [`GTAP_convert()`] as inputs, or a
#'   single HAR file holding a complete non-GTAP database (see
#'   Details).
#' @return A list of data.tables ready for input into the `.data`
#'   argument of [`ems_deploy()`]
#' @param dat_input Character vector of length 1, file name in
#'   working directory or path to a data input containing
#'   basedata coefficient data, or the corresponding "dat" list
#'   object generated by [`GTAP_convert()`].
#' @param par_input Character vector of length 1, file name in
#'   working directory or path to a data input containing
#'   parameter coefficient data, or the corresponding "par" list
#'   object generated by [`GTAP_convert()`]. `NULL` (default)
#'   together with a `NULL` `set_input` selects the single-file
#'   route.
#' @param set_input Character vector of length 1, file name in
#'   working directory or path to a data input containing set
#'   elements and attributes, or the corresponding "set" list
#'   object generated by [`GTAP_convert()`]. `NULL` (default)
#'   together with a `NULL` `par_input` selects the single-file
#'   route.
#' @param time_steps Integer vector of variable length (default
#'   is `NULL`). For use with temporally dynamic models. Input
#'   format is either chronological years of steps including
#'   initial reference year corresponding to the database
#'   employed or steps from t0 with initial value 0.
#' @param par_weights Character vector (default is `"share"`),
#'   the weights with which parameters are averaged when their
#'   sets are aggregated.
#'   * `"share"`: each member is weighted by the value of its
#'   CES or CET nest times one minus the sum of its squared
#'   input shares, so that the aggregate elasticity reproduces
#'   the members' response to a small relative price change.
#'   Members whose input shares cannot move (for example a
#'   commodity that is never imported) carry no weight.
#'   * `"value"`: each member is weighted by the value of its
#'   nest, as the FlexAgg aggregation programs do; the Armington,
#'   intermediate-input and value-added elasticities are weighted
#'   with world totals and take one value in every region, as
#'   FlexAgg writes them.
#'
#'   An unnamed element sets the method for every weighted
#'   parameter; elements named after a parameter header (e.g.
#'   `c("share", ESBM = "value")`) override it for that
#'   parameter. The CDE parameters (INCP, SUBP) are weighted by
#'   value under either method. Ignored on the single-file
#'   route, where nothing is aggregated.
#'
#'   On the GTAP-E and GTAP-Power layers ELFVAEN (EFVE) follows
#'   FlexAgg's aggpar programs: coal, oil and gas mining are
#'   recalibrated to the target supply elasticities (SPLY) and the
#'   other fuels take 1. Two results are then overridden, reported
#'   when `verbose` is on, and listed in the metadata: a
#'   recalibrated value below 0.1, which a natural-resource rent too
#'   small to carry its target produces, keeps the aggregated member
#'   value; and an aggregate whose members all carry the database
#'   placeholder 1e-6 (the technologies without energy inputs) takes
#'   1.
#' @param ... A named pairlist assigning set mappings to model
#'   sets that are explicitly read (not constructed via any set
#'   operation defined in the model file). Set mappings can be
#'   selected from a range of internally available options or
#'   provided by the user.
#'   * Internal mapping: character vector of length 1
#'   corresponding to an internally available mapping.
#'   * User-provided mapping: character vector of length 1, file
#'   name in working directory or path to a CSV file; a data
#'   frame or data frame extension (e.g., tibble, data.table).
#'
#'   See
#'   \href{https://github.com/teemsphere/teems-mappings}{teems-mappings}
#'   for internally available mappings and formatting for
#'   user-provided mappings.
#' @details Set names passed via `...` must match set names as
#'   they appear in the database. Only sets requiring aggregation
#'   need to be specified. Unspecified sets whose elements are
#'   fully covered by a provided mapping are derived
#'   automatically. Any elements not covered by a provided
#'   mapping are passed through without aggregation.
#'
#'   Single-file route: when only `dat_input` is given, the HAR
#'   file is taken as a complete database in its own right (for
#'   example the ORANI-G `basedata.har`). Every character header
#'   with distinct entries becomes a set named after its header,
#'   every real header becomes a coefficient whose dimensions are
#'   the set labels stored in the file, and the sets are passed
#'   through without aggregation. No database version is read and
#'   no set mappings may be supplied on this route.
#' @seealso [`ems_deploy()`] for loading the output of this
#'   function. [`GTAP_convert()`] for converting GTAP HAR files
#'   and data formats.
#' @examples
#' \dontrun{
#' # The following examples require input data. See
#' # https://teemsphere.github.io/ to get started.
#'
#' # Single-file database (non-GTAP), no aggregation
#' orani_data <- ems_data("oranig/basedata.har")
#'
#' # Data for a static model using internal mappings
#' v7_data <- ems_data("v7_data/gsdfdat.har",
#'                     "v7_data/gsdfpar.har",
#'                     "v7_data/gsdfset.har",
#'                     REG = "AR5",
#'                     ACTS = "food",
#'                     ENDW = "labor_diff")
#'
#' # The same aggregation with FlexAgg's value weights for the
#' # import-sourcing elasticities
#' v7_value <- ems_data("v7_data/gsdfdat.har",
#'                      "v7_data/gsdfpar.har",
#'                      "v7_data/gsdfset.har",
#'                      REG = "AR5",
#'                      ACTS = "food",
#'                      ENDW = "labor_diff",
#'                      par_weights = c(ESBM = "value"))
#'
#' # Data for an intertemporal model with explicit time steps
#' int_data <- ems_data("v6_data/gsddat.har",
#'                      "v6_data/gsdpar.har",
#'                      "v6_data/gsdset.har",
#'                      REG = "WB23",
#'                      PROD_COMM = "services",
#'                      ENDW_COMM = "labor_agg",
#'                      time_steps = c(0, 1, 2, 4, 6, 8, 10, 15))
#'
#' # Data for an intertemporal model with chronological time
#' # steps and a user-provided mapping for the ENDW set
#' int_data <- ems_data("v7_data/gsdfdat.har",
#'                      "v7_data/gsdfpar.har",
#'                      "v7_data/gsdfset.har",
#'                      REG = "R32",
#'                      ACTS = "medium",
#'                      ENDW = "user/endowment/mapping.csv",
#'                      time_steps = c(2023, 2025, 2027, 2030, 2035))
#' }           
ems_data <- function(dat_input,
                     par_input = NULL,
                     set_input = NULL,
                     time_steps = NULL,
                     par_weights = "share",
                     ...
) {
if (missing(dat_input)) {
  .cli_missing(dat_input)
}
args_list <- mget(names(formals()))
args_list$set_mappings <- list(...)
call <- match.call()
.data <- .implement_data(
  args_list = args_list,
  call = call
)
.data
}